// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 id, uint256 pick) public {
        // Wide admissible domain: pick selects between an arbitrary fuzzed id and the
        // ERC-165 supportsInterface selector (derived from c's own public surface).
        bound(pick, 0, 3);
        bytes4 probe = (pick == 0) ? c.supportsInterface.selector : id;

        // General rule: any interface id that c reports as supported may only fail to be
        // the ERC-165 selector if c does NOT support it; in particular, c must report
        // support for the ERC-165 supportsInterface selector itself.
        bool result;
        try c.supportsInterface(probe) returns (bool r) { result = r; } catch { result = false; }
        assertTrue(!(probe == c.supportsInterface.selector) || result);
    }
}
